using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using ResearchAgent;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the AI:ApiKey configuration value or OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAI.OpenAIClient(apiKey)));

builder.Services.AddSingleton<NoteStore>();
builder.Services.AddSingleton<ResearchTools>();

using var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var researchTools = host.Services.GetRequiredService<ResearchTools>();

var tools = new[]
{
    AIFunctionFactory.Create(researchTools.SearchWeb),
    AIFunctionFactory.Create(researchTools.SaveNote),
    AIFunctionFactory.Create(researchTools.GetNotes),
};

var agent = new ChatClientAgent(chatClient,
    "ResearchAgent",
    "You are a research assistant. Given a topic, search the web for information, "
    + "take notes on key findings, then provide a comprehensive summary. "
    + "Always search multiple queries to get broad coverage, save important findings as notes, "
    + "and conclude with a final summary that references your notes.");

var topic = args.Length > 0
    ? string.Join(' ', args)
    : "the latest advances in quantum computing in 2026";

Console.WriteLine($"🔬 Researching: {topic}\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User,
        $"Research the following topic thoroughly. Search for multiple aspects, "
        + $"save key findings as notes, then summarize everything.\n\nTopic: {topic}"),
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
    Tools = tools,
    Temperature = 0f,
};

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine("\n\n📝 Research Notes:");
var noteStore = host.Services.GetRequiredService<NoteStore>();
foreach (var note in noteStore.Notes)
{
    Console.WriteLine($"  • {note}");
}

