namespace ResearchAgent;

/// <summary>
/// Simple in-memory store for research notes collected during the agent session.
/// </summary>
public sealed class NoteStore
{
    private readonly List<string> _notes = [];

    public IReadOnlyList<string> Notes => _notes;

    public void Add(string note) => _notes.Add(note);
}

using System.ComponentModel;
using Microsoft.Extensions.AI;

namespace ResearchAgent;

/// <summary>
/// Tools available to the research agent for web searching and note-taking.
/// </summary>
public sealed class ResearchTools(NoteStore noteStore)
{
    private static readonly HttpClient Http = new()
    {
        Timeout = TimeSpan.FromSeconds(30),
    };

    [Description("Search the web for information on a given query. Returns relevant search result snippets.")]
    public async Task<string> SearchWeb(
        [Description("The search query to look up")] string query)
    {
        Console.WriteLine($"  🔍 Searching: {query}");

        // Uses a public search API (DuckDuckGo instant answer API) for demonstration.
        // Replace with Bing Search API or Google Custom Search for production use.
        var encoded = Uri.EscapeDataString(query);
        var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";

        try
        {
            var response = await Http.GetStringAsync(url);
            var doc = System.Text.Json.JsonDocument.Parse(response);
            var root = doc.RootElement;

            var results = new List<string>();

            var abstractText = root.GetProperty("AbstractText").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                results.Add($"Summary: {abstractText}");
            }

            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    if (topic.TryGetProperty("Text", out var text))
                    {
                        var t = text.GetString();
                        if (!string.IsNullOrWhiteSpace(t))
                        {
                            results.Add(t);
                        }
                    }
                }
            }

            return results.Count > 0
                ? string.Join("\n\n", results)
                : $"No detailed results found for '{query}'. Try a more specific search term.";
        }
        catch (Exception ex)
        {
            return $"Search failed for '{query}': {ex.Message}. Try a different query.";
        }
    }

    [Description("Save an important finding as a research note for later reference.")]
    public string SaveNote(
        [Description("The note content to save")] string note)
    {
        noteStore.Add(note);
        Console.WriteLine($"  📌 Note saved ({noteStore.Notes.Count} total)");
        return $"Note saved successfully. You now have {noteStore.Notes.Count} note(s).";
    }

    [Description("Retrieve all previously saved research notes.")]
    public string GetNotes()
    {
        if (noteStore.Notes.Count == 0)
        {
            return "No notes saved yet.";
        }

        var numbered = noteStore.Notes
            .Select((n, i) => $"{i + 1}. {n}");
        return string.Join("\n", numbered);
    }
}

